(async () => {
  const baseJuly = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round2-sQkDfX/GPAO-T5/2026-07 정산";
  const baseAug = "/private/var/folders/c7/vw1b0dhs3dddrx6r102srgvm0000gn/T/t5-round2-sQkDfX/GPAO-T5/2026-08 정산";

  // 1. 두 달 매출정산·정산내역 CSV 읽기
  const julySales = await t5.call("local_file", { action: "read", path: `${baseJuly}/2026-07 매출정산.csv` });
  const julyDetail = await t5.call("local_file", { action: "read", path: `${baseJuly}/7월 정산내역.csv` });
  const augSales = await t5.call("local_file", { action: "read", path: `${baseAug}/2026-08 매출정산.csv` });
  const augDetail = await t5.call("local_file", { action: "read", path: `${baseAug}/8월 정산내역.csv` });

  function parseCsv(text) {
    const lines = text.trim().split(/\r?\n/);
    const header = lines[0].split(",").map(h => h.trim());
    const rows = lines.slice(1).map(line => {
      const cols = line.split(",");
      const obj = {};
      header.forEach((h, i) => {
        obj[h] = (cols[i] || "").trim();
      });
      return obj;
    });
    return { header, rows };
  }

  const julySalesTable = parseCsv(julySales.text);
  const augSalesTable = parseCsv(augSales.text);

  // 숫자 열 이름을 헤더에서 추정: 총매출, 매출합계, Amount, 금액 등 후보
  function inferAmountField(header) {
    const candidates = ["총매출", "매출합계", "금액", "Amount", "amount", "총합계"];
    for (const c of candidates) {
      if (header.includes(c)) return c;
    }
    return null;
  }

  const julyAmountField = inferAmountField(julySalesTable.header);
  const augAmountField = inferAmountField(augSalesTable.header);

  function sumAmount(rows, field) {
    if (!field) return 0;
    return rows.reduce((acc, r) => {
      const v = (r[field] || "").replace(/,/g, "");
      const n = parseFloat(v);
      return acc + (isNaN(n) ? 0 : n);
    }, 0);
  }

  const julyTotal = sumAmount(julySalesTable.rows, julyAmountField);
  const augTotal = sumAmount(augSalesTable.rows, augAmountField);

  // 거래 수는 행 개수로
  const julyCount = julySalesTable.rows.length;
  const augCount = augSalesTable.rows.length;

  const diffAmount = augTotal - julyTotal;
  const diffRate = julyTotal === 0 ? null : (diffAmount / julyTotal) * 100;

  // 간단히 카테고리별 합계도 시도 ("카테고리", "상품명" 등 열 기준)
  function inferCategoryField(header) {
    const candidates = ["카테고리", "상품명", "품목", "구분", "Category", "item"];
    for (const c of candidates) {
      if (header.includes(c)) return c;
    }
    return null;
  }

  const julyCategoryField = inferCategoryField(julySalesTable.header);
  const augCategoryField = inferCategoryField(augSalesTable.header);

  function groupByCategory(rows, catField, amountField) {
    if (!catField || !amountField) return {};
    const map = {};
    for (const r of rows) {
      const cat = r[catField] || "(미분류)";
      const v = (r[amountField] || "").replace(/,/g, "");
      const n = parseFloat(v);
      if (!map[cat]) map[cat] = 0;
      if (!isNaN(n)) map[cat] += n;
    }
    return map;
  }

  const julyByCat = groupByCategory(julySalesTable.rows, julyCategoryField, julyAmountField);
  const augByCat = groupByCategory(augSalesTable.rows, augCategoryField, augAmountField);

  function formatCurrency(n) {
    return n.toLocaleString("ko-KR", { maximumFractionDigits: 0 });
  }

  function buildSummary() {
    let out = "지난달(7월) vs 이번달(8월) 매출 정산 요약\n";
    out += "====================================\n\n";
    out += "1. 전체 매출 비교\n";
    out += `- 7월 총매출: ${formatCurrency(julyTotal)}원 (거래수: ${julyCount}건)\n`;
    out += `- 8월 총매출: ${formatCurrency(augTotal)}원 (거래수: ${augCount}건)\n`;
    out += `- 증감액: ${formatCurrency(diffAmount)}원`;
    if (diffRate !== null) {
      const sign = diffRate >= 0 ? "+" : "";
      out += ` (${sign}${diffRate.toFixed(1)}%)`;
    }
    out += "\n\n";

    out += "2. 카테고리별 매출 비교 (가능한 경우)\n";
    if (Object.keys(julyByCat).length === 0 || Object.keys(augByCat).length === 0) {
      out += "- CSV 헤더에서 카테고리 열을 찾지 못해 카테고리별 비교는 생략했어요.\n\n";
    } else {
      const allCats = new Set([...Object.keys(julyByCat), ...Object.keys(augByCat)]);
      out += "카테고리, 7월 매출, 8월 매출, 증감액\n";
      for (const cat of allCats) {
        const j = julyByCat[cat] || 0;
        const a = augByCat[cat] || 0;
        const d = a - j;
        out += `- ${cat}: ${formatCurrency(j)}원 → ${formatCurrency(a)}원 (△${formatCurrency(d)}원)\n`;
      }
      out += "\n";
    }

    out += "3. 간단 코멘트\n";
    if (diffRate === null) {
      out += "- 지난달 총매출이 0으로 집계되어 증감률은 계산하지 않았어요.\n";
    } else if (diffRate > 0) {
      out += "- 이번 달 매출이 지난달보다 전반적으로 증가했어요.\n";
    } else if (diffRate < 0) {
      out += "- 이번 달 매출이 지난달보다 전반적으로 감소했어요.\n";
    } else {
      out += "- 두 달의 총매출이 거의 비슷하게 유지됐어요.\n";
    }

    out += "\n※ 이 요약은 '2026-07/08 매출정산.csv' 파일을 기준으로 자동 생성됐어요. 컬럼 구조가 다르면 실제 합계와 다를 수 있어요.\n";
    return out;
  }

  const summaryText = buildSummary();

  // 바탕화면 경로에 저장
  const desktopPath = "/Users/jyp/Desktop/지난달_vs_이번달_정산요약.txt";
  await t5.call("local_file", {
    action: "write",
    path: desktopPath,
    text: summaryText,
    source: `${baseJuly}/2026-07 매출정산.csv`
  });

  console.log({
    ok: true,
    summary: "지난달·이번달 매출정산 CSV를 비교해 요약을 만들고 바탕화면에 저장했어요.",
    result: { path: desktopPath }
  });
})();
